// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address player) public {
        vm.assume(player != address(0) && player != address(c.bank()));
        vm.deal(player, 10 ether);
        vm.prank(player);
        // Record pot before
        uint potBefore = c.pot();
        // Play
        (bool success, ) = address(c).call{value: 10}(abi.encodeWithSignature("play()"));
        if (success) {
            // If the call succeeded, then the player must have won (random == 0 in reference)
            // In that case pot should be 0 after transfer
            assertTrue(c.pot() == 0, "Pot should be zero after a winning play");
        } else {
            // If it reverted, pot should remain unchanged
            assertTrue(c.pot() == potBefore, "Pot unchanged on revert");
        }
    }
}

